const inputJson = $json || {};
const headers = inputJson.headers || {};
const body = inputJson.body || {};
const method = inputJson.method || headers['x-forwarded-method'] || 'POST';


const incomingHint = String(headers['x-correlation-id'] || headers['x-request-id'] || '').trim();
const validHint = /^[A-Za-z0-9][A-Za-z0-9._:-]{7,79}$/.test(incomingHint) ? incomingHint : '';
const incomingIdempotency = String(headers['idempotency-key'] || body.idempotencyKey || '').trim();
const validIdempotency = /^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$/.test(incomingIdempotency) ? incomingIdempotency : '';
const sha256Text = (value) => {
  const ascii = unescape(encodeURIComponent(String(value || '')));
  const rightRotate = (word, amount) => (word >>> amount) | (word << (32 - amount));
  const maxWord = Math.pow(2, 32); const words = []; let result = '';
  const bitLength = ascii.length * 8; const hash = []; const constants = []; const composite = {};
  let primeCount = 0;
  for (let candidate = 2; primeCount < 64; candidate++) {
    if (!composite[candidate]) {
      for (let multiple = candidate; multiple < 313; multiple += candidate) composite[multiple] = candidate;
      hash[primeCount] = (Math.pow(candidate, 0.5) * maxWord) | 0;
      constants[primeCount++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  let padded = ascii + '\x80';
  while (padded.length % 64 !== 56) padded += '\x00';
  for (let index = 0; index < padded.length; index++) words[index >> 2] |= padded.charCodeAt(index) << ((3 - index) % 4) * 8;
  words[words.length] = (bitLength / maxWord) | 0; words[words.length] = bitLength;
  let state = hash.slice(0, 8);
  for (let offset = 0; offset < words.length;) {
    const schedule = words.slice(offset, offset += 16); const previous = state.slice(0); state = previous.slice(0);
    for (let round = 0; round < 64; round++) {
      const w15 = schedule[round - 15], w2 = schedule[round - 2]; const a = state[0], e = state[4];
      const word = round < 16 ? schedule[round] : schedule[round] = ((rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) + schedule[round - 16] + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10)) + schedule[round - 7]) | 0;
      const temp1 = (state[7] + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) + ((e & state[5]) ^ (~e & state[6])) + constants[round] + word) | 0;
      const temp2 = ((rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) + ((a & state[1]) ^ (a & state[2]) ^ (state[1] & state[2]))) | 0;
      state = [temp1 + temp2 | 0, state[0], state[1], state[2], state[3] + temp1 | 0, state[4], state[5], state[6]];
    }
    for (let index = 0; index < 8; index++) state[index] = state[index] + previous[index] | 0;
  }
  for (let index = 0; index < 8; index++) for (let shift = 3; shift >= 0; shift--) { const byte = state[index] >> (shift * 8) & 255; result += (byte < 16 ? '0' : '') + byte.toString(16); }
  return result;
};
const hashValue = (value) => value ? sha256Text(value) : null;
const requestExecutionId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : Date.now().toString(36);
const serverRequestId = 'req-' + requestExecutionId + '-' + Date.now().toString(36);
const requestContext = {
  requestId: serverRequestId,
  correlationHintHash: hashValue(validHint),
  idempotencyKeyHash: hashValue(validIdempotency),
  startedAtEpochMs: Date.now(),
  startedAtIso: new Date().toISOString(),
  n8nExecutionId: requestExecutionId
};
if (!headers.authorization && headers.cookie) {
  const m = headers.cookie.match(/(?:^|; )auth_token=([^;]+)/);
  if (m) headers.authorization = 'Bearer ' + m[1];
}

// Láº¥y danh tÃ­nh tá»« Bearer token, khÃ´ng tin username do client tá»± gá»­i.
let username = '';
try {
  const authHeader = headers.authorization || headers.Authorization || '';
  const match = authHeader.match(/Bearer\s+(.+)/i);
  const token = match ? match[1].trim() : '';
  if (token.includes('.')) {
    const payloadPart = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
    const padding = (4 - payloadPart.length % 4) % 4;
    const payload = JSON.parse(Buffer.from(payloadPart + '='.repeat(padding), 'base64').toString('utf8'));
    username = payload.username || payload.Username || payload.UserName || payload.sub || '';
  }
} catch (error) {
  username = '';
}

const usernameSafe = String(username).replace(/'/g, "''").slice(0, 50);
const searchKeySafe = String(body.SearchKey || '').replace(/'/g, "''").slice(0, 100);

const requestOrigin = String(headers.origin || headers.Origin || '').replace(/\/$/, '');
