const authResult = $('Execute Shared Auth Guard (ListActive)').first().json;
const granted = new Set((authResult.verifiedIdentity?.capabilities || []).map(value => String(value).trim().toLowerCase()).filter(Boolean));
const readApis = new Set(["@doanh_so","@hoa_don","@hoa_don_chi_tiet","@don_hang","@cham_diem_kh","@cong_no_khach_hang","@cong_no_chi_tiet","@tich_luy","@tuyen_ban_hang","@goi_ydon_hang","@upsell_goi_y","@goi_ydon_thuoc","@danh_sach_tonkho","@tra_cuu_san_pham","@san_pham_trong_tam","@de_xuat_khuyen_mai","@danh_muc","@khao_sat360","@danh_sach_cau_hoi_khao_sat","@kiem_tra_khao_sat","@kiem_tra_khao_sat_ngay","@lich_su_khao_sat","@thong_bao","@tim_san_pham_theo_trieu_chung"]);
const mutationPolicy = {"@lap_don_hang":"orders.write","@khach_hang_insert":"customers.write","@san_pham_trong_tam_import":"products.import"};
const requiredCapabilityFor = (apiCode) => readApis.has(apiCode)
  ? 'api.read'
  : (mutationPolicy[apiCode] || null);
const canUse = (apiCode, granted) => {
  const required = requiredCapabilityFor(apiCode);
  if (!required) return false;
  const specific = apiCode.slice(1).replace(/_/g, '.');
  const candidates = [required, required.startsWith('api.read') ? 'api.read.' + specific : required + '.' + specific];
  return candidates.some(capability => granted.has(capability)) || granted.has('*') || granted.has('api:*');
};
const records = $input.all()
  .map(item => item.json || {})
  .filter(row => canUse(String(row.ApiCode || '').toLowerCase(), granted))
  .map(row => ({
    ApiCode: row.ApiCode,
    DisplayName: row.DisplayName,
    Category: row.Category,
    UiTemplate: row.UiTemplate,
    ExecutionType: row.ExecutionType
  }));
return [{ json: { records } }];

const request = $('Check Method ListActive').first().json;
const authResult = $('Execute Shared Auth Guard (ListActive)').first().json;
const context = request._requestContext || authResult._requestContext || {};
const esc = (value, max) => String(value ?? '').replace(/'/g, "''").slice(0, max);
const hashOrNull = (value) => /^[a-f0-9]{64}$/i.test(String(value || '')) ? "'" + String(value).toLowerCase() + "'" : 'NULL';
const requestId = esc(context.requestId, 100);
if (!/^req-[A-Za-z0-9._:-]{4,96}$/.test(requestId)) throw new Error('AUDIT_REQUEST_ID_INVALID');
const apiCode = esc('@api_list_active', 100) || '@unknown';
const operationType = esc('CATALOG', 20) || 'UNKNOWN';
const resultCode = esc('OK', 60) || 'UNKNOWN';
const httpStatus = Number(200) || 500;
const count = Math.max(0, Number(($json.records || []).length) || 0);
const rowCountBucket = count === 0 ? '0' : count === 1 ? '1' : count <= 10 ? '2-10' : count <= 100 ? '11-100' : '100+';
const durationMs = Math.max(0, Date.now() - Number(context.startedAtEpochMs || Date.now()));
const transactionOutcome = esc('NOT_APPLICABLE', 30) || 'NOT_APPLICABLE';
const startedAt = /^\d{4}-\d{2}-\d{2}T/.test(String(context.startedAtIso || '')) ? String(context.startedAtIso) : new Date().toISOString();
const query = `EXEC dbo.AI_WriteAPIRequestAudit
  @RequestID='${requestId}',
  @CorrelationHintHash=${hashOrNull(context.correlationHintHash)},
  @VerifiedUserHash=${hashOrNull(authResult.verifiedIdentity?.auditSubjectHash)},
  @ApiCode='${apiCode}',
  @OperationType='${operationType}',
  @ResultCode='${resultCode}',
  @HttpStatus=${httpStatus},
  @DurationMs=${durationMs},
  @RowCountBucket='${rowCountBucket}',
  @IdempotencyKeyHash=${hashOrNull(context.idempotencyKeyHash)},
  @TransactionOutcome='${transactionOutcome}',
  @N8nExecutionID='${esc(context.n8nExecutionId, 80)}',
  @StartedAt='${esc(startedAt, 30)}';`;
return [{ json: { query } }];

